      motilidadGlobal: "conservada",
      septumIA: "Indemnes",
      trombosMasas: "Sin trombos ni masas intracavitarias",
      vegetaciones: "Aparatos valvulares libres",
      aoMorf: "Tricúspide, de características normales, apertura y cierre conservados",
